   if(player){b.withMethodBody("getActiveWeaponItem",MethodTypeDesc.of(ClassDesc.of("org.l2jmobius.gameserver.entity.item.Weapon")),1,c->c.aconst_null().areturn());b.withMethodBody("getCurrentMp",MethodTypeDesc.of(CD_double),1,c->c.aload(0).invokestatic(host,"mp",MethodTypeDesc.of(CD_double,cr)).dreturn());b.withMethodBody("getKnownSkill",MethodTypeDesc.of(desc(Skill.class),CD_int),1,c->c.aload(0).iload(1).invokestatic(host,"known",MethodTypeDesc.of(desc(Skill.class),desc(Player.class),CD_int)).areturn());b.withMethodBody("isSkillDisabled",MethodTypeDesc.of(CD_boolean,desc(Skill.class)),1,c->c.aload(0).aload(1).invokestatic(host,"skillDisabled",MethodTypeDesc.of(CD_boolean,desc(Player.class),desc(Skill.class))).ireturn());b.withMethodBody("getAutoPlaySettings",MethodTypeDesc.of(desc(AutoPlaySettingsHolder.class)),1,c->c.aload(0).invokestatic(host,"settings",MethodTypeDesc.of(desc(AutoPlaySettingsHolder.class),desc(Player.class))).areturn());b.withMethodBody("getAutoUseSettings",MethodTypeDesc.of(desc(AutoUseSettingsHolder.class)),1,c->c.aload(0).invokestatic(host,"uses",MethodTypeDesc.of(desc(AutoUseSettingsHolder.class),desc(Player.class))).areturn());b.withMethodBody("getParty",MethodTypeDesc.of(desc(Party.class)),1,c->c.aload(0).invokestatic(host,"party",MethodTypeDesc.of(desc(Party.class),desc(Player.class))).areturn());b.withMethodBody("getSummon",MethodTypeDesc.of(desc(Summon.class)),1,c->c.aconst_null().areturn());}
