 static Creature actor(boolean player,int x)throws Exception{Creature p=(Creature)u.allocateInstance(player?playerType:mobType);Actor a=new Actor();a.id=ids++;a.x=x;ACTORS.put(p,a);Field f=WorldObject.class.getDeclaredField("_location");f.setAccessible(true);f.set(p,new Location(x,0,0));if(player){a.ai=new RecordingAI(p);a.uses.getAutoSkills().add(attackSkill.getId());}return p;}
