 static final ClassFile CANON=ClassFile.of(ClassFile.ConstantPoolSharingOption.NEW_POOL,ClassFile.DebugElementsOption.DROP_DEBUG,ClassFile.LineNumbersOption.DROP_LINE_NUMBERS,ClassFile.StackMapsOption.DROP_STACK_MAPS);
 static String fp(MethodModel m)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(CANON.build(m.parent().orElseThrow().thisClass().asSymbol(),b->b.transformMethod(m,MethodTransform.transformingCode((cb,e)->{if(e instanceof Instruction||e instanceof LabelTarget||e instanceof ExceptionCatch)cb.with(e);})))));}
 static String key(MethodModel m){return m.methodName().stringValue()+m.methodType().stringValue();}
 static byte[] bind(byte[] input,boolean reverse)throws Exception{
  var cf=ClassFile.of(ClassFile.ClassHierarchyResolverOption.of(ClassHierarchyResolver.ofResourceParsing(ClassLoader.getSystemClassLoader()).orElse(ClassHierarchyResolver.defaultResolver())));var model=cf.parse(input);ClassDesc host=desc(AutoPlayNativeCheck.class),world=desc(World.class),geo=desc(GeoEngine.class),pm=desc(PhantomManager.class);
  return cf.transformClass(model,ClassTransform.transformingMethodBodies((b,e)->{
   if(e instanceof InvokeInstruction i){var owner=i.owner().asSymbol();String n=i.name().stringValue();var type=MethodTypeDesc.ofDescriptor(i.type().stringValue());
    if(!reverse&&owner.equals(desc(System.class))&&n.equals("currentTimeMillis")){b.invokestatic(host,"now",type);return;}
    if(!reverse&&owner.equals(world)&&n.equals("getNearestVisibleObjectInRange")){b.invokestatic(host,"nearest",type);return;}
    if(!reverse&&owner.equals(world)&&n.equals("getFirstVisibleObjectInRange")){b.invokestatic(host,"first",type);return;}
    if(!reverse&&owner.equals(world)&&n.equals("findObject")){b.invokestatic(host,"find",type);return;}
    if(!reverse&&owner.equals(geo)&&n.equals("getInstance")){b.invokestatic(host,"geo",type);return;}
    if(!reverse&&owner.equals(geo)&&n.equals("canSeeTarget")){b.invokestatic(host,"see",type.insertParameterTypes(0,geo));return;}
    if(!reverse&&owner.equals(geo)&&n.equals("canMoveToTarget")){b.invokestatic(host,"moveAllowed",type.insertParameterTypes(0,geo));return;}
    if(!reverse&&owner.equals(pm)&&n.equals("getInstance")){b.invokestatic(host,"pm",type);return;}
    if(!reverse&&owner.equals(pm)&&n.equals("isPhantom")){b.invokestatic(host,"phantom",type.insertParameterTypes(0,pm));return;}
    if(reverse&&owner.equals(host))switch(n){case"now"->{b.invokestatic(desc(System.class),"currentTimeMillis",type);return;}case"nearest"->{b.invokestatic(world,"getNearestVisibleObjectInRange",type);return;}case"first"->{b.invokestatic(world,"getFirstVisibleObjectInRange",type);return;}case"find"->{b.invokestatic(world,"findObject",type);return;}case"geo"->{b.invokestatic(geo,"getInstance",type);return;}case"see"->{b.invokevirtual(geo,"canSeeTarget",type.dropParameterTypes(0,1));return;}case"moveAllowed"->{b.invokevirtual(geo,"canMoveToTarget",type.dropParameterTypes(0,1));return;}case"pm"->{b.invokestatic(pm,"getInstance",type);return;}case"phantom"->{b.invokevirtual(pm,"isPhantom",type.dropParameterTypes(0,1));return;}}
   }b.with(e);
  }));
 }
 static ClassLoader loader(Path after)throws Exception{
  return new ClassLoader(AutoPlayNativeCheck.class.getClassLoader()){@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{
   if(!(name.startsWith("org.l2jmobius.gameserver.taskmanagers.AutoPlayTaskManager")||name.startsWith("org.l2jmobius.gameserver.taskmanagers.EpilogueAutoPlayProgress")||(after!=null&&name.equals(AutoPlayConfig.class.getName()))))return super.loadClass(name,resolve);
   synchronized(getClassLoadingLock(name)){Class<?> c=findLoadedClass(name);if(c==null)try{String resource=name.replace('.','/')+".class";Path p=after==null?null:after.resolve(resource);byte[] raw=p!=null&&Files.isRegularFile(p)?Files.readAllBytes(p):getParent().getResourceAsStream(resource).readAllBytes();byte[] bound=bind(raw,false),restored=bind(bound,true);var a=CANON.parse(raw);var z=CANON.parse(restored);Map<String,String> hashes=new HashMap<>();for(var m:z.methods())hashes.put(key(m),fp(m));for(var m:a.methods())if(!fp(m).equals(hashes.get(key(m))))throw new AssertionError("fixture altered method beyond reversible World/geo/clock bindings "+name+key(m));c=defineClass(name,bound,0,bound.length);}catch(Throwable e){throw new ClassNotFoundException(name,e);}if(resolve)resolveClass(c);return c;}
  }};
 }
 static Object task(Player p)throws Exception{Class<?> outer=codeLoader.loadClass("org.l2jmobius.gameserver.taskmanagers.AutoPlayTaskManager"),inner=codeLoader.loadClass(outer.getName()+"$AutoPlay");Object manager=u.allocateInstance(outer);var ctor=inner.getDeclaredConstructor(outer,Set.class);ctor.setAccessible(true);return ctor.newInstance(manager,Set.of(p));}
 static void tick(Object task,long now){time=now;((Runnable)task).run();}
 static void selected()throws Exception{
  ACTORS.clear();NEARBY.clear();Player p=(Player)actor(true,0);Monster blocked=(Monster)actor(false,400),alternative=(Monster)actor(false,600);ACTORS.get(blocked).reachable=false;NEARBY.add(blocked);NEARBY.add(alternative);p.setTarget(blocked);Object task=task(p);
  tick(task,100000);check(p.getTarget()==blocked,"initial selected mage goal retained");tick(task,120001);check(p.getTarget()==(fixed?alternative:blocked),"selected stuck mob20s before/after");System.out.println("SELECTED_STUCK fixed="+fixed+" target="+p.getTarget().getObjectId()+" blocked="+blocked.getObjectId()+" alternate="+alternative.getObjectId());
  ACTORS.get(blocked).reachable=true;p.setTarget(null);tick(task,120700);check(p.getTarget()==(fixed?alternative:blocked),"normal predicate cannot immediately reacquire blocked mob");p.setTarget(null);tick(task,180002);check(p.getTarget()==blocked,"normal predicate permits same mob after60s expiry");System.out.println("BLACKLIST_SELECTED fixed="+fixed+" immediate_reacquire="+!fixed+" expiry_permits_old=true");
 }
 static void walking()throws Exception{
  ACTORS.clear();NEARBY.clear();Player p=(Player)actor(true,0);Monster blocked=(Monster)actor(false,400);ACTORS.get(blocked).reachable=false;NEARBY.add(blocked);Object task=task(p);tick(task,100000);check(p.getTarget()==null&&p.isMoving(),"actual walkAround starts ordinary detour without selected target");tick(task,120001);check(p.isMoving()!=fixed,"moving-without-target no longer bypasses timeout");Monster alternate=(Monster)actor(false,600);NEARBY.add(alternate);ACTORS.get(blocked).reachable=true;tick(task,120700);check(p.getTarget()==(fixed?alternate:blocked),"detour blacklist also applies to normal search");p.setTarget(null);tick(task,180002);check(p.getTarget()==blocked,"detour blacklist expires after60s");System.out.println("WALKING_DETOUR fixed="+fixed+" timed_out="+fixed+" alternate_after_timeout="+fixed);
 }
 static void protectedProgress()throws Exception{
  for(String kind:List.of("stun","cast","short_attack_stamp","short_cast_stamp","hp_drop","unusable_skill")){
   ACTORS.clear();NEARBY.clear();Player p=(Player)actor(true,0);Monster blocked=(Monster)actor(false,400),alternate=(Monster)actor(false,600);ACTORS.get(blocked).reachable=false;NEARBY.add(blocked);NEARBY.add(alternate);p.setTarget(blocked);Actor a=ACTORS.get(p);if(kind.equals("short_attack_stamp"))a.uses.getAutoActions().add(2);if(kind.equals("unusable_skill"))a.skillDisabled=true;Object task=task(p);tick(task,100000);
   switch(kind){case"stun"->a.stun=true;case"cast"->a.casting=true;case"hp_drop"->ACTORS.get(blocked).hp=900;case"short_attack_stamp"->{Field f=Creature.class.getDeclaredField("_attackEndTime");f.setAccessible(true);f.setLong(p,50L);a.attackTarget=blocked;check(f.getLong(p)==50L,"actual private Native attack stamp changed");}case"short_cast_stamp"->{Field f=Creature.class.getDeclaredField("_castInterruptTime");f.setAccessible(true);f.setInt(p,50);Field last=Creature.class.getDeclaredField("_lastSkillCast");last.setAccessible(true);last.set(p,attackSkill);check(p.getCastInterruptTime()==50&&p.getLastSkillCast()==attackSkill,"actual Native negative cast stamp changed");}}
   tick(task,119000);a.stun=false;a.casting=false;tick(task,120001);check(p.getTarget()==blocked,"legitimate activity/blocked skill does not falsely timeout "+kind);System.out.println("PROTECTED_PROGRESS "+kind+" fixed="+fixed+" kept=true");
  }
 }
