  ACTORS.clear();NEARBY.clear();p=(Player)actor(true,0);Monster raid=(Monster)actor(false,200),normal=(Monster)actor(false,400);ACTORS.get(raid).raid=true;NEARBY.add(raid);NEARBY.add(normal);tick(task(p),100000);check(p.getTarget()==normal,"real monster mode excludes raid and selects normal mob");System.out.println("TARGET_MODES fixed="+fixed+" native_predicates_kept=true");
